def _extract_ast_skeleton(self, code: str, symbol_type: str, symbol_name: str) -> str:
    """
    Creates a high-level AST skeleton preserving signatures and types
    while stripping inner implementation details to save prompt tokens.
    """
    lines = code.splitlines()
    if len(lines) <= 4:
        return code

    # Extract header/signature
    header = []
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("def ") or stripped.startswith("class ") or stripped.startswith("async def "):
            header.append(line)
        elif stripped.startswith("@") or stripped.startswith("export ") or stripped.startswith("func "):
            header.append(line)
        elif stripped.startswith('"""') or stripped.startswith("'''"):
            header.append(line)
            break
        elif not header and stripped:
            header.append(line)
        elif header and stripped.endswith("):") or stripped.endswith("->") or stripped.endswith("{"):
            header.append(line)
            break

    sig = "\n".join(header) if header else lines[0]
    return f"{sig}\n    # [AST Skeleton: Implementation pruned - saves ~70% tokens]\n    ..."

def index_codebase(
    self,
    paths: Optional[List[Path]] = None,
    max_files: int = 1000
) -> Dict[str, Any]:
    """
    Builds sparse inverted index and dense embedding vectors across codebase files.
    """
    scan_paths = paths or [
        self.repo_root / "workplace",
        self.repo_root / ".nb",
        self.repo_root / "user"
    ]

    target_exts = {".py", ".ts", ".js", ".yaml", ".yml", ".json", ".md"}
    all_files: List[Path] = []
    for p in scan_paths:
        if p.is_file() and p.suffix in target_exts:
            all_files.append(p)
        elif p.is_dir():
            for f in p.rglob("*"):
                if f.is_file() and f.suffix in target_exts:
                    if not any(part in f.parts for part in (".git", "__pycache__", ".scratch", "node_modules")):
                        all_files.append(f)
                if len(all_files) >= max_files:
                    break

    self.chunks.clear()
    self.inverted_index.clear()
    self.doc_lengths.clear()

    total_tokens = 0
    for f in all_files:
        file_chunks = self.extract_chunks_from_file(f)
        for c in file_chunks:
            self.chunks[c.chunk_id] = c
            doc_len = len(c.tokens)
            self.doc_lengths[c.chunk_id] = doc_len
            total_tokens += doc_len

            # Update inverted index
            for t in set(c.tokens):
                if t not in self.inverted_index:
                    self.inverted_index[t] = set()
                self.inverted_index[t].add(c.chunk_id)

    self.avg_doc_len = total_tokens / max(len(self.chunks), 1)
    self.save_index()

    return {
        "status": "INDEXED",
        "indexed_files": len(all_files),
        "indexed_chunks": len(self.chunks),
        "vocabulary_size": len(self.inverted_index),
        "avg_doc_len": round(self.avg_doc_len, 2),
        "updated_at": datetime.now(timezone.utc).isoformat()
    }

def _cosine_similarity(self, v1: List[float], v2: List[float]) -> float:
    """Computes cosine similarity between two normalized vectors."""
    if not v1 or not v2 or len(v1) != len(v2):
        return 0.0
    return sum(a * b for a, b in zip(v1, v2))

def load_index(self) -> bool:
    """Loads index from disk if present."""
    meta_file = self.index_dir / "vector_index_meta.json"
    if not meta_file.exists():
        return False

    try:
        data = json.loads(meta_file.read_text(encoding="utf-8"))
        self.avg_doc_len = data.get("avg_doc_len", 0.0)
        self.chunks.clear()
        self.inverted_index.clear()
        self.doc_lengths.clear()

        for item in data.get("chunks", []):
            chunk = CodeChunk(**item)
            self.chunks[chunk.chunk_id] = chunk
            self.doc_lengths[chunk.chunk_id] = len(chunk.tokens)
            for t in set(chunk.tokens):
                if t not in self.inverted_index:
                    self.inverted_index[t] = set()
                self.inverted_index[t].add(chunk.chunk_id)

        return True
    except Exception:
        return False

class AgentCapabilityGuard:
    """
    Validates HMAC-SHA256 capability tokens and enforces sandbox boundaries
    across filesystem operations, subprocess execution, and network egress.
    """

    DEFAULT_SECRET: str = "percipience_cbac_secret_enclave_key_2026"

    PROTECTED_DIRS = [
        ".nb/core",
        ".nb/context/rules",
        ".nb/context/invariants",
        ".git"
    ]

    WHITELISTED_COMMANDS = {
        "pytest", "git", "python3", "python", "node", "npm", "tsc", "pyright", "ruff", "flake8"
    }

    BLOCKED_COMMANDS = {
        "curl", "wget", "rm", "nc", "netcat", "bash", "sh", "zsh", "pip", "chmod", "chown", "dd", "mkfs"
    }

    LOOPBACK_HOSTS = {"127.0.0.1", "localhost", "::1"}

    @classmethod

def verify_token(
    cls,
    token_str: str,
    secret_key: Optional[str] = None
) -> Tuple[bool, Optional[Dict[str, Any]], Optional[str]]:
    """
    Verifies the cryptographic signature and expiration of a capability token.
    Returns (is_valid, payload, error_message).
    """
    secret = (secret_key or cls.DEFAULT_SECRET).encode("utf-8")
    parts = token_str.split(".")
    if len(parts) != 2:
        return False, None, "PERMISSION_DENIED_INVALID_TOKEN: Malformed token structure"

    encoded_payload, signature = parts
    expected_sig = hmac.new(secret, encoded_payload.encode("utf-8"), hashlib.sha256).hexdigest()

    if not hmac.compare_digest(signature, expected_sig):
        return False, None, "PERMISSION_DENIED_INVALID_TOKEN: Invalid cryptographic signature"

    try:
        raw_json = base64.urlsafe_b64decode(encoded_payload.encode("utf-8")).decode("utf-8")
        payload = json.loads(raw_json)
    except Exception:
        return False, None, "PERMISSION_DENIED_INVALID_TOKEN: Payload decode error"

    if time.time() > payload.get("expires_at", 0):
        return False, payload, "PERMISSION_DENIED_EXPIRED_TOKEN: Capability token has expired"

    return True, payload, None

@classmethod

def check_fs_access(
    cls,
    token_str: str,
    target_path: str,
    operation: str = "write",
    repo_root: Optional[Path] = None
) -> Tuple[bool, Optional[str]]:
    """
    Checks whether the token allows reading or writing the target file.
    Intercepts traversal attacks and protects platform core assets.
    """
    valid, payload, err = cls.verify_token(token_str)
    if not valid:
        return False, err

    allowed_ops = payload.get("allowed_operations", [])
    worktree_p = Path(payload.get("worktree_path", "")).resolve()
    target_p = Path(target_path).resolve()
    root = repo_root or REPO_ROOT

    # 1. Operation capability check
    if operation == "read":
        if "CAP_FS_READ" not in allowed_ops:
            return False, "PERMISSION_DENIED_OPERATION_NOT_PERMITTED: CAP_FS_READ required"
        return True, None

    if operation == "write":
        if "CAP_FS_WRITE_MODULE_ONLY" not in allowed_ops and "CAP_FS_WRITE" not in allowed_ops:
            return False, "PERMISSION_DENIED_OPERATION_NOT_PERMITTED: CAP_FS_WRITE_MODULE_ONLY required"

        # 2. Protected directories check (e.g. .nb/core, .nb/context/rules, .git)
        for protected in cls.PROTECTED_DIRS:
            protected_abs = (root / protected).resolve()
            if target_p == protected_abs or protected_abs in target_p.parents:
                return False, f"PERMISSION_DENIED_PATH_RESTRICTED: Write forbidden to protected directory '{protected}'"

        # 3. Worktree path containment check (must be inside assigned worktree)
        try:
            target_p.relative_to(worktree_p)
        except ValueError:
            return False, f"PERMISSION_DENIED_PATH_RESTRICTED: Path '{target_path}' is outside assigned worktree '{worktree_p}'"

        return True, None

    return False, f"PERMISSION_DENIED_UNKNOWN_OPERATION: Operation '{operation}' unrecognized"

@classmethod

def check_subprocess_command(
    cls,
    token_str: str,
    command: Any
) -> Tuple[bool, Optional[str]]:
    """
    Validates command execution against the capability token and command whitelist.
    Blocks dangerous binaries and shell escapes.
    """
    valid, payload, err = cls.verify_token(token_str)
    if not valid:
        return False, err

    allowed_ops = payload.get("allowed_operations", [])
    if "CAP_EXEC_SUBPROCESS" not in allowed_ops:
        return False, "PERMISSION_DENIED_OPERATION_NOT_PERMITTED: CAP_EXEC_SUBPROCESS required"

    # Extract binary name
    if isinstance(command, str):
        parts = shlex.split(command)
    elif isinstance(command, (list, tuple)):
        parts = list(command)
    else:
        return False, "PERMISSION_DENIED_INVALID_COMMAND: Command must be string or list"

    if not parts:
        return False, "PERMISSION_DENIED_INVALID_COMMAND: Empty command"

    binary = Path(parts[0]).name.lower()

    # 1. Hard blocked check
    if binary in cls.BLOCKED_COMMANDS:
        return False, f"PERMISSION_DENIED_UNAUTHORIZED_COMMAND: Command '{binary}' is strictly prohibited"

    # Check for dangerous arguments like rm -rf
    full_cmd_str = " ".join(parts).lower()
    if "rm -rf" in full_cmd_str or "rm -r" in full_cmd_str:
        return False, "PERMISSION_DENIED_UNAUTHORIZED_COMMAND: Recursive removal command prohibited"

    # 2. Whitelist check
    if binary not in cls.WHITELISTED_COMMANDS:
        return False, f"PERMISSION_DENIED_UNAUTHORIZED_COMMAND: Binary '{binary}' is not on the execution whitelist"

    return True, None

@classmethod

def estimate_tokens(cls, text: str) -> int:
    """Estimates token count using character heuristics (~4 chars/token)."""
    if not text:
        return 0
    return max(1, int(len(text) / cls.CHARS_PER_TOKEN))

@classmethod

def slice_context(
    cls,
    sections: Dict[str, str],
    max_total_tokens: int = 8192
) -> Dict[str, Any]:
    """
    Calculates section token distributions and bounds each section within its quota.
    """
    quota_tokens = {
        k: int(max_total_tokens * weight)
        for k, weight in cls.BUDGET_QUOTAS.items()
    }

    adjusted_sections: Dict[str, str] = {}
    section_token_metrics: Dict[str, Dict[str, Any]] = {}
    total_used_tokens = 0

    for section_key, quota in quota_tokens.items():
        if section_key == "reserved_output":
            continue

        raw_text = sections.get(section_key, "")
        raw_tokens = cls.estimate_tokens(raw_text)

        if raw_tokens <= quota:
            adjusted_text = raw_text
            trimmed_tokens = 0
        else:
            if section_key == "persona_invariants":
                # Invariants must never be truncated
                adjusted_text = raw_text
                trimmed_tokens = 0
            else:
                # Proportionally trim text to fit quota
                max_chars = int(quota * cls.CHARS_PER_TOKEN)
                adjusted_text = raw_text[:max_chars] + "\n... [ATTENTION_TRUNCATED_TO_PRESERVE_BUDGET]"
                trimmed_tokens = raw_tokens - cls.estimate_tokens(adjusted_text)

        current_tokens = cls.estimate_tokens(adjusted_text)
        total_used_tokens += current_tokens

        section_token_metrics[section_key] = {
            "allocated_quota_tokens": quota,
            "raw_tokens": raw_tokens,
            "adjusted_tokens": current_tokens,
            "trimmed_tokens": max(0, trimmed_tokens),
            "quota_utilization_pct": round((current_tokens / quota) * 100, 2)
        }
        adjusted_sections[section_key] = adjusted_text

    # Assemble unified attention-sliced prompt
    assembled_prompt = (
        f"=== SYSTEM INVARIANTS & PERSONA ===\n{adjusted_sections.get('persona_invariants', '')}\n\n"
        f"=== WIRE CONTRACTS & SCHEMAS ===\n{adjusted_sections.get('contracts_schemas', '')}\n\n"
        f"=== AST CODEBASE CONTEXT ===\n{adjusted_sections.get('ast_codebase', '')}\n\n"
        f"=== EPISODIC MEMORY & TRAJECTORIES ===\n{adjusted_sections.get('memory_trajectories', '')}\n"
    )

    return {
        "status": "SLICED_SUCCESSFULLY",
        "max_total_tokens": max_total_tokens,
        "total_used_tokens": total_used_tokens,
        "reserved_output_tokens": quota_tokens["reserved_output"],
        "remaining_headroom_tokens": max_total_tokens - total_used_tokens,
        "section_metrics": section_token_metrics,
        "assembled_prompt": assembled_prompt
    }

