                    "token": lock_token,
                    "acquired_at_ms": now_ms,
                    "expires_at_ms": now_ms + ttl_ms,
                    "ttl_ms": ttl_ms
                }
                return lock_token

        if attempt < retry_count - 1:
            time.sleep(retry_delay_ms / 1000.0)

    return None

