def reclaim_stale_leases(cls, workspace_root: Path) -> List[str]:
    """Active eviction: identifies and purges leases with dead PIDs or expired TTLs."""
    leases = cls.list_leases(workspace_root)
    reclaimed = []
    for l in leases:
