def _tokenize(cls, text: str) -> List[str]:
    """Normalizes, stems simple plurals, and filters stopwords."""
    raw_words = re.findall(r"\b[a-zA-Z0-9_]+\b", text.lower())
    tokens = []
    for w in raw_words:
