def scan_and_track_repo(
    cls,
    repo_root: Path = REPO_ROOT,
    target_dir: Optional[str] = None,
    session_or_pr: str = "ci_gatekeeper",
    model_id: str = "claude-3-5-sonnet-20241022"
) -> Dict[str, Any]:
    """
    Scans codebase files (.ts, .py, .go, .rs), prunes them using ASTOptimizer,
    and logs token savings events to the ledger using batch transactions.
    """
    search_root = (repo_root / target_dir) if target_dir else (repo_root / "workplace")
    extensions = [".ts", ".py", ".go", ".rs", ".js"]
    raw_events = []

    if not search_root.exists():
        return {"scanned_files": 0, "events": [], "summary": {}}

    for root, _, files in os.walk(search_root):
        if any(p in root for p in [".git", "node_modules", ".workspaces", "__pycache__", ".nb"]):
            continue
        for f in files:
            if any(f.endswith(ext) for ext in extensions):
                file_path = Path(root) / f
                try:
                    content = file_path.read_text(encoding="utf-8", errors="ignore")
                    if len(content.strip()) < 40:
                        continue

                    # Determine language
                    ext = file_path.suffix.lstrip(".")
                    lang = "typescript" if ext in ["ts", "js"] else ("python" if ext == "py" else ext)

                    _, stats = ASTOptimizer.prune_source(content, lang)
                    if stats["saved_tokens"] > 0:
                        rel_path = str(file_path.relative_to(repo_root))
                        raw_events.append({
                            "file_path": rel_path,
                            "uncompressed_tokens": stats["uncompressed_tokens"],
                            "pruned_tokens": stats["pruned_tokens"],
                            "session_or_pr": session_or_pr,
                            "model_id": model_id
                        })
                except Exception:
                    continue

    recorded_events = cls.record_events_batch(repo_root, raw_events)
    ledger = cls.load_ledger(repo_root)
    cls.generate_markdown_report(repo_root)
    return {
        "scanned_files": len(recorded_events),
        "new_events_count": len(recorded_events),
        "summary": ledger.get("summary", {})
    }

@classmethod

def estimate_tokens(cls, text: str) -> int:
    """Estimates token count using character heuristics (~4 chars/token)."""
    if not text:
        return 0
    return max(1, int(len(text) / cls.CHARS_PER_TOKEN))

@classmethod

def slice_context(
    cls,
    sections: Dict[str, str],
    max_total_tokens: int = 8192
) -> Dict[str, Any]:
    """
    Calculates section token distributions and bounds each section within its quota.
    """
    quota_tokens = {
        k: int(max_total_tokens * weight)
        for k, weight in cls.BUDGET_QUOTAS.items()
    }

    adjusted_sections: Dict[str, str] = {}
    section_token_metrics: Dict[str, Dict[str, Any]] = {}
    total_used_tokens = 0

    for section_key, quota in quota_tokens.items():
        if section_key == "reserved_output":
            continue

        raw_text = sections.get(section_key, "")
        raw_tokens = cls.estimate_tokens(raw_text)

        if raw_tokens <= quota:
            adjusted_text = raw_text
            trimmed_tokens = 0
        else:
            if section_key == "persona_invariants":
                # Invariants must never be truncated
                adjusted_text = raw_text
                trimmed_tokens = 0
            else:
                # Proportionally trim text to fit quota
                max_chars = int(quota * cls.CHARS_PER_TOKEN)
                adjusted_text = raw_text[:max_chars] + "\n... [ATTENTION_TRUNCATED_TO_PRESERVE_BUDGET]"
                trimmed_tokens = raw_tokens - cls.estimate_tokens(adjusted_text)

        current_tokens = cls.estimate_tokens(adjusted_text)
        total_used_tokens += current_tokens

        section_token_metrics[section_key] = {
            "allocated_quota_tokens": quota,
            "raw_tokens": raw_tokens,
            "adjusted_tokens": current_tokens,
            "trimmed_tokens": max(0, trimmed_tokens),
            "quota_utilization_pct": round((current_tokens / quota) * 100, 2)
        }
        adjusted_sections[section_key] = adjusted_text

    # Assemble unified attention-sliced prompt
