def hash_file(file_path: Path) -> str:
    if not file_path.is_file():
        return "0" * 64
    sha = hashlib.sha256()
    with open(file_path, "rb") as f:
        while chunk := f.read(65536):
            sha.update(chunk)
    return sha.hexdigest()

