    ]
    for v in violations:
        lines.append(f"- [{v.get('type')}] ({v.get('severity')}): {v.get('description')} (target: `{v.get('target', 'N/A')}`)")
    lines.append("Enforce safe APIs only: do not use eval, shell=True, forbidden paths, or hallucinated imports.")
    return "\n".join(lines)

