    projectedTokenSavingsUsd: Math.round(grossSavings),
    revShareFeeUsd: Math.round(revShareFee),
    netClientMonthlySavingsUsd: Math.round(netMonthly),
    annualizedRoiUsd: Math.round(annualized),
  };
}

