                    z.write(f, arcname)

        # 2. Add Kotlin source files (for source JAR & SDK inspection)
        if src_kotlin.exists():
            for f in src_kotlin.rglob("*.kt"):
                if f.is_file():
                    arcname = "src/" + str(f.relative_to(src_kotlin))
                    z.write(f, arcname)

