class WorkflowOrchestrator:
    """
    Executes declarative workflow DAGs with support for parallel fan-out groups,
    barrier joins, dependency satisfaction, and token metering.
    """

    @classmethod

def load_workflow(cls, workflow_path: Path) -> Dict[str, Any]:
    """Loads and validates a workflow YAML specification, normalizing steps and stages."""
    if not workflow_path.exists():
        raise FileNotFoundError(f"Workflow definition not found at: {workflow_path}")
    with open(workflow_path, "r", encoding="utf-8") as f:
        data = yaml.safe_load(f) or {}

    workflow_id = data.get("workflow_id") or data.get("name") or data.get("id") or workflow_path.stem
    raw_steps = data.get("steps") or data.get("stages") or []
    if not workflow_id or not raw_steps:
        raise ValueError(f"Invalid workflow schema in {workflow_path}: missing workflow_id/steps/stages")

    normalized_steps = []
    for s in raw_steps:
        if isinstance(s, dict):
            norm_s = dict(s)
            norm_s["id"] = s.get("id") or s.get("step_id") or s.get("stage_id") or f"step_{len(normalized_steps)}"
            norm_s["executor"] = s.get("executor") or s.get("agent") or "generic_executor"
            normalized_steps.append(norm_s)

    data["workflow_id"] = workflow_id
    data["steps"] = normalized_steps
    return data

@classmethod

def _execute_single_step(
    cls,
    step: Dict[str, Any],
    executors: Dict[str, Callable],
    context: Dict[str, Any]
) -> Dict[str, Any]:
    """Executes a single workflow step."""
    sid = step["id"]
    executor_key = step.get("executor", sid)
    func = executors.get(executor_key) or executors.get(sid)

    start_time = time.time()
    if func:
        try:
            res = func(step=step, context=context)
            duration = round(time.time() - start_time, 4)
            return {
                "step_id": sid,
                "name": step.get("name", sid),
                "status": res.get("status", "SUCCESS"),
                "output": res,
                "duration_sec": duration
            }
        except Exception as e:
            duration = round(time.time() - start_time, 4)
            return {
                "step_id": sid,
                "name": step.get("name", sid),
                "status": "FAILED",
                "error": str(e),
                "duration_sec": duration
            }
    else:
        # Simulated default success handler for built-in step definitions
        time.sleep(0.005)
        duration = round(time.time() - start_time, 4)
        return {
            "step_id": sid,
            "name": step.get("name", sid),
            "status": "SUCCESS",
            "output": {"message": f"Step {sid} executed successfully"},
            "duration_sec": duration
        }

@classmethod

def _execute_parallel_group(
    cls,
    steps: List[Dict[str, Any]],
    executors: Dict[str, Callable],
    max_workers: int,
    context: Dict[str, Any]
) -> Dict[str, Dict[str, Any]]:
    """Executes multiple workflow steps concurrently using ThreadPoolExecutor."""
    results: Dict[str, Dict[str, Any]] = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(len(steps), max_workers)) as pool:
        future_to_step = {
            pool.submit(cls._execute_single_step, s, executors, context): s["id"]
            for s in steps
        }
        for future in concurrent.futures.as_completed(future_to_step):
            sid = future_to_step[future]
            try:
                res = future.result()
                results[sid] = res
            except Exception as e:
                results[sid] = {
                    "step_id": sid,
                    "status": "FAILED",
                    "error": str(e),
                    "duration_sec": 0.0
                }
    return results

